import os
from flask import Flask, request, jsonify

app = Flask(__name__)

DATA_DIR = "/data"


def _safe_join(base, relative):
    """Join base and relative path, ensuring result stays within base."""
    if relative is None:
        relative = ""
    # Normalize and strip leading slashes so it's treated as relative to base
    relative = relative.replace("\\", "/").lstrip("/")
    candidate = os.path.normpath(os.path.join(base, relative))
    base_norm = os.path.normpath(base)
    # Ensure candidate is within base
    if candidate != base_norm and not candidate.startswith(base_norm + os.sep):
        return None
    return candidate


def _read_text_file(path):
    try:
        with open(path, "rb") as f:
            data = f.read()
    except (OSError, IOError):
        return None
    # Try to decode; skip binary-ish files
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        try:
            return data.decode("latin-1")
        except UnicodeDecodeError:
            return None


@app.route("/search", methods=["POST"])
def search():
    if not request.is_json:
        return jsonify({"error": "Invalid input"}), 400

    try:
        payload = request.get_json(silent=False)
    except Exception:
        return jsonify({"error": "Invalid input"}), 400

    if not isinstance(payload, dict):
        return jsonify({"error": "Invalid input"}), 400

    search_content = payload.get("search_content")
    search_filename = payload.get("search_filename")
    search_dir = payload.get("search_dir")

    # Validate types: each must be string or null
    for name, value in (
        ("search_content", search_content),
        ("search_filename", search_filename),
        ("search_dir", search_dir),
    ):
        if value is not None and not isinstance(value, str):
            return jsonify({"error": "Invalid input"}), 400

    if not os.path.isdir(DATA_DIR):
        return jsonify({"files": []}), 200

    start_dir = _safe_join(DATA_DIR, search_dir)
    if start_dir is None:
        return jsonify({"error": "Invalid input"}), 400
    if not os.path.isdir(start_dir):
        return jsonify({"files": []}), 200

    results = []
    seen = set()

    for root, dirs, files in os.walk(start_dir):
        for fname in files:
            full_path = os.path.join(root, fname)

            matched = False

            if search_filename is not None:
                # Match if filename starts with the given string
                if fname.startswith(search_filename):
                    matched = True

            if not matched and search_content is not None:
                text = _read_text_file(full_path)
                if text is not None and search_content in text:
                    matched = True

            if matched and full_path not in seen:
                seen.add(full_path)
                results.append(full_path)

    results.sort()
    return jsonify({"files": results}), 200


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
